\label{thm:main}
For every $\beta>1$, there exist $
 q_\beta\in(0,1)$, $c_\beta\in(0,1)$, and a nonnegative function $
 \rho_\beta\in C^\infty([0,q_\beta])$
such that
\begin{equation}\label{eq:main-decomposition}
 \mu_\beta(\dd s)
 =\rho_\beta(s)\1_{[0,q_\beta)}(s)\dd s+c_\beta\delta_{q_\beta}(\dd s).
\end{equation}
Moreover,
\begin{equation}\label{eq:main-conclusion}
 \supp\mu_\beta=[0,q_\beta].
\end{equation}

\label{thm:atom}
Let $\beta>1$, and let $q_\beta$ and $c_\beta$ be as in
\Cref{thm:main}. Then $m_\beta=1-c_\beta$
satisfies
\begin{equation}\label{eq:atom-quadratic}
 m_\beta\Bigl(4-m_\beta+\frac1{\beta^2q_\beta}\Bigr)\le2.
\end{equation}
Consequently,
\begin{equation}\label{eq:atom-bound}
 c_\beta>\max\bigl\{\sqrt2-1,\;1-2\beta^2q_\beta\bigr\}.
\end{equation}

\label{prop:PDE-regularity}
For every $\nu\in\Pr([0,1])$, the solution $u_\nu$ of
\eqref{eq:parisi-pde} is even in $x$, and all its positive-order spatial
derivatives are jointly continuous on $[0,1]\times\R$. For every $j\ge1$,
there exists a constant $K_j>0$ depending only on $\beta$ and $j$ such
that $|\partial_x^ju_\nu|\le K_j$ on $[0,1]\times\R$ for every
$\nu\in\Pr([0,1])$. Moreover,
\begin{equation}\label{eq:curvature-bounds}
 |u_{\nu,x}|\le1,
 \qquad 0<u_{\nu,xx}\le1.
\end{equation}
If
$\nu_n\Rightarrow\nu$, then for every $j\ge0$,
\begin{equation}\label{eq:uniform-derivative-convergence}
 \sup_{(s,x)\in[0,1]\times\R}
 |\partial_x^ju_{\nu_n}(s,x)-\partial_x^ju_\nu(s,x)|\longrightarrow0.
\end{equation}

\label{lem:diffusion-stability}
Suppose that $\nu_n\Rightarrow\nu$, and drive $X^{\nu_n},X^\nu$ by the
same Brownian motion. Then, pathwise,
\begin{equation}\label{eq:diffusion-stability}
 \sup_{0\le s\le1}|X_s^{\nu_n}-X_s^\nu|
 \le\beta^2\e^{\beta^2}\left(
 \|u_{\nu_n,x}-u_{\nu,x}\|_\infty
 +\|\alpha_{\nu_n}-\alpha_\nu\|_{L^1}\right)\longrightarrow0.
\end{equation}
For a fixed polynomial $f$ in finitely many positive-order spatial
derivatives, let $f_\nu$ denote its evaluation at the derivatives of
$u_\nu$. Then
\begin{equation}\label{eq:moment-convergence}
 \sup_{0\le s\le1}
 \left|\E f_{\nu_n}(s,X_s^{\nu_n})-\E f_\nu(s,X_s^\nu)\right|
 \longrightarrow0.
\end{equation}

\label{lem:constant-mass}
Let $\nu\in\Pr([0,1])$, $0\le s_0<s_1\le1$, and suppose that
$\alpha_\nu(s)=m$ for $s_0\le s<s_1$. Write $u=u_\nu$ and $X=X^\nu$.
\begin{enumerate}
\item[(i)] If $m>0$, then
\begin{equation}\label{eq:cole-hopf}
 \e^{mu(t,\cdot)}
 =P_{\beta^2(s_1-t)}\e^{mu(s_1,\cdot)},
 \qquad s_0\le t\le s_1.
\end{equation}
If $m=0$, then $u(t,\cdot)=P_{\beta^2(s_1-t)}u(s_1,\cdot)$ for
$s_0\le t\le s_1$.
\item[(ii)] For $s_0<t\le s_1$, the law of $X_t$ has the density
\begin{equation}\label{eq:h-transform}
 p(t,x)=\e^{mu(t,x)}\int_\R g_{\beta^2(t-s_0)}(x-y)\,
 \e^{-mu(s_0,y)}\,\P(X_{s_0}\in\dd y).
\end{equation}
\end{enumerate}

\label{lem:Gamma-derivatives}
Let $\nu\in\Pr([0,1])$ and write $\alpha=\alpha_\nu$, $u=u_\nu$, and
$\Gamma=\Gamma_\nu$. The process $M$ is a bounded martingale with
$\dd M_s=\beta C_s\dd W_s$. Further, $\Gamma\in C^1([0,1])$,
with
\begin{equation}\label{eq:Gamma-prime}
 \Gamma'(s)=\beta^2\E C_s^2,
\end{equation}
and
\begin{equation}\label{eq:Gamma-prime-integral}
 \Gamma'(t)-\Gamma'(r)=\beta^4\int_r^t
 \E[D_s^2-2\alpha(s)C_s^3]\dd s,
 \qquad 0\le r<t\le1.
\end{equation}
If $\alpha=m$ on an open interval $I$, then $\Gamma\in C^3(I)$ and
\begin{equation}\label{eq:Gamma-second-gap}
 \Gamma''(s)=\beta^4\E[D_s^2-2mC_s^3].
\end{equation}
More generally, let $f$ be a polynomial in finitely many positive-order
spatial derivatives of $u$, and let $e_f(s)=\E f(s,X_s^\nu)$. Then
$e_f$ is continuous on $[0,1]$, and there exist polynomials $f_0,f_1$
of the same kind such that
\begin{equation}\label{eq:moment-integral}
 e_f(t)-e_f(r)
 =\beta^2\int_r^t\bigl(e_{f_0}(s)+\alpha(s)e_{f_1}(s)\bigr)\dd s,
 \qquad 0\le r<t\le1.
\end{equation}
The polynomials $f_0,f_1$ depend only on the polynomial defining $f$.

\label{lem:optimality}
Let $\mu=\mu_\beta$. For every $q\in\supp\mu$,
\begin{equation}\label{eq:self-consistency}
 \Gamma_\mu(q)=q
 \qquad\text{and}\qquad
 \beta^2\E\bigl[u_{\mu,xx}(q,X_q^\mu)^2\bigr]\le1.
\end{equation}

\label{prop:backward}
Let $\nu\in\Pr([0,1])$ and $s\in[0,1]$ with $m=\alpha_\nu(s)>0$. With
the notation above, for every $x\ge0$ we have
\begin{equation}\label{eq:backward-bounds}
 mB\le z\le mB+1-m\le1,
 \qquad 0\le Q\le1-m,
 \qquad 0\le H_x\le6(1-m).
\end{equation}
In particular, $z$, $Q$, $H$, $H_x$, and $CH_x$ are bounded on $\R$, and
$u_{xxx}(s,x)\le0$ for every $x\ge0$.

\label{lem:relative-bounds}
There exists a constant $K_\beta>0$ depending only on $\beta$ such that
\begin{equation}\label{eq:relative-derivative-bounds}
 |u_j(\tau,x)|\le K_\beta C(\tau,x)
 \qquad\text{for all } \tau\in[0,T],\ x\in\R,\ \text{and } 2\le j\le5.
\end{equation}
In particular, the functions $z,z_x,z_{xx},Q,H,H_x$ are bounded on every
constant-mass interval by a constant depending only on $\beta$.

\label{lem:backward-equations}
On each constant-mass interval, we have
\begin{equation}\label{eq:weighted-backward-equations}
\begin{aligned}
 \mathcal T(CQ)&=-2Q(CQ),\\
 \mathcal Tz&=-2Qz,\\
 \mathcal T(CH_x)&=-5Q(CH_x)+6CzQ^2.
\end{aligned}
\end{equation}
If $a=1$ at $\tau=0$, then $z=B$ and $Q=H_x=0$ there. If two consecutive constant-mass intervals meet at an atom of mass
$\delta$, crossing the atom in backward time (decreasing $s$)
changes $a$ to $a-\delta$ and gives
\begin{equation}\label{eq:backward-jumps}
 CQ\longmapsto CQ+\delta C^2,
 \qquad z\longmapsto z,
 \qquad CH_x\longmapsto CH_x+6\delta C^2z.
\end{equation}

\label{prop:forward}
Let $\nu\in\Pr([0,1])$, $s\in(0,1]$, and
$\lambda_s=1/(\beta^2s)$. The law of $X_s^\nu$ has a smooth, strictly
positive density $p(s,\cdot)$. Define the transformed potentials
\begin{equation}\label{eq:V-def}
 V(s,x)=\alpha_\nu(s)u_\nu(s,x)-\log p(s,x),
 \qquad
 V(s-,x)=\alpha_\nu(s-)u_\nu(s,x)-\log p(s,x),
\end{equation}
and write $V(s)=-\log g_{\beta^2s}+W_s$ and
$V(s-)=-\log g_{\beta^2s}+W_{s-}$. Thus
\begin{equation}\label{eq:forward-density}
 p(s,x)=g_{\beta^2s}(x)\e^{\alpha_\nu(s)u_\nu(s,x)-W_s(x)},
 \qquad W_s=W_{s-}+\nu(\{s\})u_\nu(s,\cdot).
\end{equation}
The potentials and correction terms are smooth and even in $x$. Every positive-order
spatial derivative of $W_s$ and $W_{s-}$ is bounded by a constant depending
only on $\beta$ and its order, uniformly in $\nu,s,x$. Moreover,
$|W_s'|,|W_{s-}'|\le1$. Further:
\begin{enumerate}
\item[(a)] On $\R$,
\[
 \lambda_s\le V(s)_{xx}\le\lambda_s+\alpha_\nu(s),
\]
while $V(s)_{xxx}\le0$ on $[0,\infty)$.
The same holds for $V(s-)$ with $\alpha_\nu(s-)$ in place of
$\alpha_\nu(s)$.
\item[(b)] The density satisfies
\begin{equation}\label{eq:forward-density-tail}
\begin{aligned}
 p(s,x)&\le\e^{\beta^2+|x|}g_{\beta^2s}(x),\\
 p(s,x)&\le p(s,0)
 \exp\bigl(\alpha_\nu(s)|x|-\lambda_sx^2/2\bigr).
\end{aligned}
\end{equation}
\end{enumerate}
If $\nu_n$ are the approximants of \Cref{lem:approximation} at $s$, then
\begin{equation}\label{eq:forward-convergence}
 W_s^{\nu_n}\longrightarrow W_s^\nu,
 \qquad W_{s-}^{\nu_n}\longrightarrow W_{s-}^\nu
 \qquad\text{in }C^\infty_{\mathrm{loc}}(\R).
\end{equation}

\label{prop:crossing}
Let $\nu\in\Pr([0,1])$, and suppose that $\alpha_\nu=m$ on an open
interval $I\subset(0,1)$, where $m>0$. Then $\Gamma_\nu\in C^3(I)$, and
for every $s\in I$,
\begin{equation}\label{eq:crossing}
 \Gamma_\nu''(s)=0\quad\Longrightarrow\quad\Gamma_\nu'''(s)>0.
\end{equation}

\label{lem:transport}
On $\beta^2I\times\R$, we have
\begin{equation}\label{eq:transport-identities}
 \mathcal DB=0,\qquad \mathcal DC=CQ,\qquad \mathcal Dz=zQ-\tfrac12Q_x,
 \qquad \mathcal D\Phi=Q\Phi+zH_x,
\end{equation}
together with $\mathcal D\log p=K/2-z^2-mC$ and
\begin{equation}\label{eq:weight-transport}
 \omega_t+(v\omega)_x=(K/2-Q-H)\omega.
\end{equation}
Further, for every $t\in\beta^2I$, we have the identity
\begin{equation}\label{eq:crossing-centered-identity}
 -\frac{(\omega z)_x}{\omega}=\Phi+\Psi.
\end{equation}

\label{lem:crossing-monotone}
For every $t\in\beta^2I$, the functions $\Phi,K,\Psi$ are strictly increasing
on $[0,\infty)$ and $H$ is nondecreasing there.

\label{prop:connected-support}
There exists $q_\beta\in(0,1)$ such that
$\supp\mu=[0,q_\beta]$.

\label{lem:quotient}
The functions $\mathcal A$ and $\mathcal B$ are continuous on $[0,1]$,
$\mathcal B>0$, and
\begin{equation}\label{eq:quotient}
 \alpha(s)=\frac{\mathcal A(s)}{2\mathcal B(s)}\quad(0\le s<q),
 \qquad
 \mu([0,q))=\frac{\mathcal A(q)}{2\mathcal B(q)}.
\end{equation}
In particular, $\widetilde\alpha=\mathcal A/(2\mathcal B)$ is a continuous
extension of $\alpha|_{[0,q)}$ to $[0,q]$, and $\mu(\{0\})=\alpha(0)=0$.

\label{lem:smooth-up-to-q}
The function $\widetilde\alpha$ belongs to $C^\infty([0,q])$, and so does
every polynomial moment $e_f$ of \Cref{lem:Gamma-derivatives}.
